    local v16 = tbl15.GetTargetParts(v15)
    if #v16 < 1 then
        return
    end
    local reRegisterHit = v14["RE/RegisterHit"]
    v14["RE/RegisterAttack"]:FireServer(tbl15.Rate)
    reRegisterHit:FireServer(v16[1][2], v16)
end

