-- Halloween ESP: labels Halloween event objects, enemies, pumpkins and doors.
local HalloweenESPEnabled = false
local HalloweenESPFolderName = "CATHUB_HalloweenESP"
local HalloweenESPKeywords = {
    "halloween", "pumpkin", "jack", "dapper", "hellfire", "trick", "treat",
    "cursed", "witch", "candycorn", "candy corn", "spooky"
}

local function IsHalloweenESPObject(instance)
    local name = string.lower(instance.Name or "")
    for _, keyword in ipairs(HalloweenESPKeywords) do
        if string.find(name, keyword, 1, true) then
            return true
        end
    end
    return false
end

local function GetHalloweenESPPart(instance)
    if instance:IsA("BasePart") then
        return instance
    end
    if instance:IsA("Model") then
        return instance.PrimaryPart or instance:FindFirstChild("HumanoidRootPart") or instance:FindFirstChildWhichIsA("BasePart", true)
    end
    return nil
end

local function ClearHalloweenESP()
    for _, instance in ipairs(workspace:GetDescendants()) do
        if instance.Name == HalloweenESPFolderName then
            instance:Destroy()
        end
    end
end

Core.HalloweenESP = function(enabled)
    HalloweenESPEnabled = enabled == true
    if not HalloweenESPEnabled then
        ClearHalloweenESP()
    end
end

local function UpdateHalloweenESP()
    if not HalloweenESPEnabled then
        return
    end
    local character = game:GetService("Players").LocalPlayer.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if not root then return end

    for _, instance in ipairs(workspace:GetDescendants()) do
        if (instance:IsA("Model") or instance:IsA("BasePart")) and IsHalloweenESPObject(instance) then
            local part = GetHalloweenESPPart(instance)
            if part and part:IsDescendantOf(workspace) then
                local gui = part:FindFirstChild(HalloweenESPFolderName)
                if not gui then
                    gui = Instance.new("BillboardGui")
                    gui.Name = HalloweenESPFolderName
                    gui.Adornee = part
                    gui.AlwaysOnTop = true
                    gui.Size = UDim2.fromOffset(180, 36)
                    gui.StudsOffset = Vector3.new(0, 2.5, 0)
                    gui.Parent = part
                    local label = Instance.new("TextLabel")
                    label.Name = "Label"
                    label.BackgroundTransparency = 1
                    label.Size = UDim2.fromScale(1, 1)
                    label.Font = Enum.Font.GothamBold
                    label.TextSize = 13
                    label.TextColor3 = Color3.fromRGB(255, 190, 70)
                    label.TextStrokeTransparency = 0.25
                    label.Parent = gui
                end
                local label = gui:FindFirstChild("Label")
                if label then
                    local distance = math.floor((root.Position - part.Position).Magnitude / 3)
                    label.Text = instance.Name .. "  |  " .. distance .. " m"
                end
            end
        end
    end
end

task.spawn(function()
    while task.wait(0.75) do
        pcall(UpdateHalloweenESP)
    end
end)

