        v20 = v21
    elseif tbl18 then
        v20 = tbl18[1]
    else
        v20 = v18
    end

    if not v20 then
        return
    end

    if not arg.FlipCard and filtergc then
        arg.FlipCard = filtergc("function", {Constants = {"Flip", "GameId", "CellIndex"}}, true)
    end

