    local v21 = getthreadidentity
    local n7 = v21 and getthreadidentity() or 8

    if setthreadidentity then
        setthreadidentity(2)
    end

    local ok, result = pcall(arg.FlipCard, ConcentrationGame, v20)

    if setthreadidentity then
