local roseWindow = devNiulaiLua:CreateWindow({
    Title = "CAT HUB : Blox Fruits",
    Subtitle = "Created by CATJack.gg",
    Icon = "rbxassetid://126031329785796",
    Version = "CAT HUB",
    Theme = "Rose",
    Keybind = Enum.KeyCode.LeftControl,
    ToggleButton = {Icon = "cat"},
    OpenButton = false,
    SaveFile = "CAT_HUB_BloxFruits",
})

-- Compatibility adapter: keep the existing CAT HUB tabs/buttons and callbacks,
-- while rendering them with the Rose Petals GUI controls.
v = {}
function v:MakeTab(config)
    local roseTab = roseWindow:Tab({Name = config.Title or "Tab", Icon = config.Icon})
    local activeSection = roseTab
    local tabProxy = {}

    function tabProxy:AddSection(name)
        activeSection = roseTab:Section({Name = name})
        return activeSection
    end

    function tabProxy:AddToggle(config)
        return activeSection:Toggle({
            Name = config.Name,
            Description = config.Description,
            Default = config.Default,
            Callback = config.Callback,
            Flag = config.Flag,
        })
    end

    function tabProxy:AddButton(config)
        return activeSection:Button({
            Name = config.Name,
            Description = config.Description,
            Callback = config.Callback,
            Icon = config.Icon,
        })
    end

    function tabProxy:AddDropdown(config)
        return activeSection:Dropdown({
            Name = config.Name,
            Description = config.Description,
            Options = config.Options or config.Values or {},
            Default = config.Default or config.CurrentOption,
            Multi = config.Multi == true,
            Callback = config.Callback,
            Flag = config.Flag,
        })
    end

    function tabProxy:AddSlider(config)
        return activeSection:Slider({
            Name = config.Name,
            Description = config.Description,
            Min = config.Min or 0,
            Max = config.Max or 100,
            Default = config.Default or config.CurrentValue or 0,
            Step = config.Increment or config.Step or 1,
            Suffix = config.Suffix,
            Callback = config.Callback,
            Flag = config.Flag,
        })
    end

    function tabProxy:AddTextBox(config)
        return activeSection:Input({
            Name = config.Name,
            Description = config.Description,
            Placeholder = config.Placeholder or config.Default or "",
            Default = config.Default or "",
            Callback = config.Callback,
            Flag = config.Flag,
        })
    end

    function tabProxy:AddParagraph(title, content)
        local paragraph = activeSection:Paragraph({Name = title, Content = content})
        return {
            Set = function(_, value)
                if paragraph and paragraph.Set then paragraph:Set(value) end
            end,
            SetDesc = function(_, value)
                if paragraph and paragraph.Set then paragraph:Set(value) end
            end,
        }
    end

    return tabProxy
end

function v:Notify(config)
    return roseWindow:Notify({
        Title = config.Title or "CAT HUB",
        Content = config.Content or config.Text or "",
        Duration = config.Duration or 3,
        Type = config.Type,
    })
end

function v:SetUIScale(scale)
    return roseWindow:SetUIScale(scale)
end

-- The Rose Petals window has its own built-in mobile toggle button.
function v:NewMinimizer()
    return {CreateMobileMinimizer = function() end}
end

tbl = {
        Info = v:MakeTab({Title = "Tab Info And Status", Icon = "Info"}),
        Main = v:MakeTab({Title = "Tab Farming", Icon = "rbxassetid://7733960981"}),
        Settings = v:MakeTab({Title = "Tab Setting", Icon = "rbxassetid://7734053495"}),
        Halloween = v:MakeTab({Title = "Tab Halloween", Icon = "ghost"}),
        Fish = v:MakeTab({
            Title = "Tab Fishing",
            Icon = "rbxassetid://127664059821666",
        }),
        Quests = v:MakeTab({
            Title = "Tab Quest And Item",
            Icon = "rbxassetid://13075622619",
        }),
        SeaEvent = v:MakeTab({Title = "Tab Sea Event", Icon = "waves"}),
        Race = v:MakeTab({
            Title = "Tab Mirage And Race",
            Icon = "rbxassetid://11162889532",
        }),
        Prehistoric = v:MakeTab({Title = "Tab Volcano Event", Icon = "tent"}),
        Esp = v:MakeTab({
            Title = "Tab Stats And Esp",
            Icon = "rbxassetid://7040410130",
        }),
        Raids = v:MakeTab({
            Title = "Tab Fruit And Raid",
            Icon = "rbxassetid://11155986081",
        }),
        Combat = v:MakeTab({
            Title = "Tab Local Player",
            Icon = "rbxassetid://13075651575",
        }),
        Travel = v:MakeTab({Title = "Tab Teleport", Icon = "locate"}),
        Shop = v:MakeTab({Title = "Tab Shopping", Icon = "rbxassetid://6031265976"}),
        Misc = v:MakeTab({
            Title = "Tab Miscellaneous",
            Icon = "rbxassetid://10709783577",
        }),
    }

    tbl.Halloween:AddSection("Halloween Event")
    local v3 = tbl.Halloween:AddParagraph("Halloween Status", "Waiting for event core")

    for i, v4 in ipairs({
        {
            "TrickOrTreat",
            "Auto Trick Or Treat",
            "Ready doors, rewards, matching cards and your door's enemies.",
        },
        {
            "Pumpkins",
            "Auto Farm Pumpkins",
            "Break nearby pumpkins for Candy Corn and Pumpkin Bits.",
        },
        {
            "Jack",
            "Auto Kill Event Enemy",
            "Fight randomly spawned Jack o' Lantern enemies.",
        },
        {
            "Bosses",
            "Auto Halloween Bosses",
            "Fight spawned Hellfire and Great Pumpkin bosses.",
        },
        {
            "Summon",
            "Auto Summon Great Pumpkin",
            "Use 3 Cursed Pumpkin Seeds and 200 Pumpkin Bits at the Witch.",
        },
        {
            "Gacha",
            "Auto Spooky Gacha",
            "Check Candy Corn Before Rolling.",
        },
    }) do
        local v5 = v4[1]

        tbl.Halloween:AddToggle({
            Name = v4[2],
            Description = v4[3],
            Default = false,
            Callback = function(arg)
                if Core and Core.Halloween then
                    Core.Halloween:SetEnabled(v5, arg)
                elseif arg then
                    v:Notify({
                        Title = "Halloween",
                        Content = "Load the updated core before enabling Halloween.",
                        Duration = 5,
                    })
                end
            end,
        })
    end

    tbl.Halloween:AddToggle({
        Name = "Halloween ESP",
        Description = "Show labels and distance for Halloween event objects, enemies, pumpkins and doors.",
        Default = false,
        Callback = function(enabled)
            if Core and Core.HalloweenESP then
                Core.HalloweenESP(enabled)
            end
        end,
    })

    task.spawn(function()
        while task.wait(1) do
            if Core and Core.Halloween then
                v3:SetDesc(Core.Halloween.Status)
            end
        end
    end)

    tbl.Info:AddSection("CAT HUB Branding")
    tbl.Info:AddParagraph("CAT HUB", "Created and branded by CATJack.gg")
    tbl.Info:AddParagraph("Discord", "Join the CAT HUB community: discord.gg/KckKFJWzs6")
    tbl.Info:AddParagraph("Logo", "CAT HUB official logo")

    tbl.Info:AddSection("Status Server")
    local v4 = tbl.Info:AddParagraph("Time Zone", "")
    local v5 = tbl.Info:AddParagraph("Game Time", "")

    UpdateOS = function()
        local v6 = os.date("*t")
        local n = v6.hour % 24
        local str = n < 12 and "AM" or "PM"
        local str2 = string.format("%02i:%02i:%02i %s", (n - 1) % 12 + 1, v6.min, v6.sec, str)
        local str3 = string.format("%02d/%02d/%04d", v6.day, v6.month, v6.year)
        local LocalizationService = game:GetService("LocalizationService")
        local localPlayer = game:GetService("Players").LocalPlayer
        local countryRegionCode

        if getgenv().countryRegionCode then
            countryRegionCode = getgenv().countryRegionCode
        else
            local ok, countryRegionCode2 = pcall(function()
                return LocalizationService:GetCountryRegionForPlayerAsync(localPlayer)
            end)

            countryRegionCode = countryRegionCode2

            if ok then
                getgenv().countryRegionCode = countryRegionCode2
            else
                getgenv().countryRegionCode = "Unknown"
            end
        end

        v4:SetDesc(str3 .. " - " .. str2 .. " [ " .. countryRegionCode .. " ]")
    end

    spawn(function()
        while true do
            UpdateOS()
            wait(1)
        end
    end)

    UpdateGameTime = function()
        local n = math.floor(workspace.DistributedGameTime + 0.5)
        local n2 = math.floor(n / 3600) % 24
        local n3 = math.floor(n / 60) % 60
        local n4 = math.floor(n / 1) % 60
        v5:SetDesc(n2 .. " Hour (h) " .. n3 .. " Minute (m) " .. n4 .. " Second (s)")
    end

    spawn(function()
        while true do
            UpdateGameTime()
            wait(1)
        end
    end)

    local v6 = tbl.Info:AddParagraph("Mirage Island", "Status: ")
    local str = ""

    spawn(function()
        pcall(function()
            while true do
                wait(1)
                local flag = game.Workspace._WorldOrigin.Locations:FindFirstChild("Mirage Island") ~= nil
                local status = flag and "✅" or "❌"

                if status ~= str then
                    v6:SetDesc("Status: " .. status)
                    str = status
                end
            end
        end)
    end)

    local v7 = tbl.Info:AddParagraph("Kitsune Island", "Status: ")
    local str2 = ""

    spawn(function()
        while task.wait(1) do
            pcall(function()
                local kitsuneIsland = game:GetService("Workspace").Map:FindFirstChild("KitsuneIsland")
                local status = kitsuneIsland and "✅" or "❌"

                if status ~= str2 then
                    v7:SetDesc("Status: " .. status)
                    str2 = status
                end
            end)
        end
    end)

    local v8 = tbl.Info:AddParagraph("Prehistoric Island", "Status: ")
    local str3 = ""

    task.spawn(function()
