local v6 = tbl.Travel:AddToggle({
    Name = "Auto Travel",
    Description = "",
    Default = false,
    Callback = function(teleport)
        local v6, v7, v8, v9, v10, v11, n
        n = 1

        while true do
            if n == 1 then
                _G.Teleport = teleport

                if teleport then
                    n = 2
                else
                    n = 6
                end
            elseif n == 2 then
                v6, v7, v8 = pairs(workspace._WorldOrigin.Locations:GetChildren())
                v9 = v8
                n = 3
            elseif n == 3 then
                v10, v11 = v6(v7, v9)

                if v10 == nil then
                    n = 6
                else
                    n = 4
                end
            elseif n == 4 then
                v9 = v10

                if v11.Name == _G.Island then
                    n = 5
                else
                    n = 3
                end
            elseif n == 5 then
                wait()
                _tp(v11.CFrame * CFrame.new(0, 30, 0))

                if _G.Teleport and Root.CFrame ~= v11.CFrame then
                    n = 5
                else
                    n = 3
                end
            elseif n == 6 then
                return
            end
        end
    end,
})

